mapper.select:
SELECT u.user_id
FROM tb_user u
         JOIN tb_login_account la ON la.login_id = u.login_id
WHERE la.tenant_id = #{tenantId}
  AND la.login_code = #{loginCode}
    LIMIT 1

mapper.sql:
SELECT i.common_code_item_id FROM tb_common_code_item i JOIN tb_common_code_group g ON g.common_code_group_id = i.group_id WHERE i.tenant_id = #{tenantId}
AND (g.group_code, i.item_code) NOT IN
(#{d.groupCode}, #{d.code})

SELECT common_code_group_id
FROM tb_common_code_group
WHERE tenant_id = #{tenantId}

    AND group_code NOT IN

        #{g.groupCode}
